// PaymentService — supposed to be choreography: react to OrderPlaced
class PaymentService {
  async handleOrderPlaced(event: OrderPlacedEvent) {
    // Charge the customer
    await this.chargeCustomer(event.customerId, event.amount);

    // Directly call InventoryService to notify it
    await this.inventoryClient.reserveStock(event.orderId, event.items);

    // Emit event after calling inventory (so inventory is already done)
    await this.eventBus.emit('PaymentProcessed', { orderId: event.orderId });
  }
}

// OrderSaga — supposed to be orchestration
class OrderSaga {
  async run(orderId: string) {
    const order = await this.orderRepo.findById(orderId);

    // Step 1: charge
    const charged = await this.paymentClient.charge(order.customerId, order.amount);

    // Step 2: check credit tier and decide shipping speed
    if (order.customerTier === 'gold') {
      await this.shippingClient.scheduleExpressDelivery(orderId);
    } else {
      await this.shippingClient.scheduleStandardDelivery(orderId);
    }

    // Step 3: format and send invoice email inline
    const invoiceHtml = this.buildInvoiceHtml(order, charged);
    await this.emailClient.send(order.customerEmail, 'Your invoice', invoiceHtml);
  }

  private buildInvoiceHtml(order: Order, charged: ChargeResult): string {
    return `<html><body>Order ${order.id} total: ${charged.amount}</body></html>`;
  }
}

