class OrderSaga {
  async run(orderId: string): Promise<void> {
    const saga = await this.sagaRepo.create({ orderId, status: 'started', completedSteps: [] });
    await this.eventBus.emit('SagaStarted', { sagaId: saga.id, orderId });

    // Step 1: Charge (delegate tier logic to PaymentService)
    try {
      const payResult = await this.paymentClient.processPayment({ orderId, tier: saga.order.customerTier });
      await this.sagaRepo.recordStep(saga.id, 'payment', payResult);
      await this.eventBus.emit('SagaStepCompleted', { sagaId: saga.id, step: 'payment' });
    } catch (e) {
      return this.compensate(saga, e);
    }

    // Step 2: Reserve inventory
    try {
      const invResult = await this.inventoryClient.reserveStock({ orderId, items: saga.order.items });
      await this.sagaRepo.recordStep(saga.id, 'inventory', invResult);
      await this.eventBus.emit('SagaStepCompleted', { sagaId: saga.id, step: 'inventory' });
    } catch (e) {
      return this.compensate(saga, e);
    }

    // Step 3: Schedule shipment
    try {
      const shipResult = await this.shippingClient.schedule({ orderId });
      await this.sagaRepo.recordStep(saga.id, 'shipping', shipResult);
      await this.eventBus.emit('SagaStepCompleted', { sagaId: saga.id, step: 'shipping' });
    } catch (e) {
      return this.compensate(saga, e);
    }

    await this.sagaRepo.complete(saga.id);
    await this.eventBus.emit('SagaCompleted', { sagaId: saga.id, orderId });
  }

  private async compensate(saga: SagaState, error: Error): Promise<void> {
    await this.eventBus.emit('SagaCompensating', { sagaId: saga.id, reason: error.message });
    // Run compensations in reverse for completed steps
    for (const step of [...saga.completedSteps].reverse()) {
      if (step.name === 'shipping') await this.shippingClient.cancel({ orderId: saga.orderId });
      if (step.name === 'inventory') await this.inventoryClient.releaseStock({ orderId: saga.orderId });
      if (step.name === 'payment') await this.paymentClient.refund({ orderId: saga.orderId });
    }
    await this.sagaRepo.fail(saga.id, error.message);
    await this.eventBus.emit('SagaFailed', { sagaId: saga.id, reason: error.message });
  }
}

// Key decisions:
// - sagaRepo.recordStep() persists saga state before continuing — survives restarts
// - paymentClient.processPayment({ tier }) delegates gold-tier logic to PaymentService
// - compensate() reads completedSteps from persisted saga state — works after restart
// - All events emitted via eventBus (should use outbox pattern for reliability)

